import { PageFlip } from "page-flip";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createRoot, type Root } from "react-dom/client";

import { BlankPage } from "../BlankPage";
import { CoverWrapper } from "../covers/CoverWrapper";
import { GreetingPage } from "../GreetingPage";
import { useAutoplay } from "../hooks/useAutoplay";
import { useSpreads } from "../hooks/useSpreads";
import { pairSplitGreetings } from "../utils/pairSpreads";
import type { AlbumSlide, LayoutViewProps } from "../types";

/** Narrowest a single leaf may get; also decides when two of them fit. */
const MIN_PAGE_WIDTH = 260;

/** How far a finger travels before it counts as a page turn rather than a tap. */
const SWIPE_THRESHOLD = 40;

/**
 * Hardcover book layout.
 *
 * StPageFlip has no RTL mode, so the whole book is mirrored on the X axis and
 * each page's content is mirrored back. That makes the spread order, the spine
 * position and the turn direction all match a Hebrew book without reordering
 * the data. The mirror does invert pointer coordinates, so the library's own
 * mouse handling is disabled and turns are driven by click zones, the control
 * buttons, the keyboard and the autoplay ticker instead.
 */
export function PageFlipView({
  album,
  slides,
  autoplay,
  autoplaySpeed,
  loop,
  showControls,
  onPageChange,
}: LayoutViewProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const flipRef = useRef<PageFlip | null>(null);
  const [current, setCurrent] = useState(0);
  const [total, setTotal] = useState(slides.length);
  const [interacted, setInteracted] = useState(false);

  // Spacers only make sense while two leaves are visible at once, so the book
  // is rebuilt with or without them as the window crosses the threshold.
  const spreads = useSpreads(hostRef, MIN_PAGE_WIDTH * 2);
  const leaves = useMemo(
    () => (spreads ? pairSplitGreetings(slides) : slides),
    [slides, spreads],
  );

  const changeRef = useRef(onPageChange);
  changeRef.current = onPageChange;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;

    // StPageFlip removes its own root element on destroy(), so it is handed a
    // throwaway child rather than the div React holds a ref to. Without this,
    // a remount (StrictMode, layout switch) leaves the book detached.
    const mount = document.createElement("div");
    mount.className = "ae-flip__mount";
    host.appendChild(mount);

    const roots: Root[] = [];
    const pageElements = leaves.map((slide) => {
      const el = document.createElement("div");
      el.className = "ae-flip__page";
      el.setAttribute("data-density", coverDensity(slide));
      const inner = document.createElement("div");
      inner.className = "ae-flip__inner";
      el.appendChild(inner);

      const root = createRoot(inner);
      root.render(renderLeaf(album, slide));
      roots.push(root);
      mount.appendChild(el);
      return el;
    });

    const book = new PageFlip(mount, {
      width: 460,
      height: 620,
      size: "stretch",
      minWidth: MIN_PAGE_WIDTH,
      maxWidth: 900,
      minHeight: 340,
      maxHeight: 1200,
      showCover: true,
      usePortrait: true,
      autoSize: true,
      drawShadow: true,
      maxShadowOpacity: 0.4,
      flippingTime: 700,
      useMouseEvents: false,
      mobileScrollSupport: false,
      swipeDistance: 0,
    });

    book.loadFromHTML(pageElements);
    flipRef.current = book;
    setTotal(book.getPageCount());
    setCurrent(book.getCurrentPageIndex());

    book.on("flip", (event) => {
      const index = Number(event.data);
      if (Number.isNaN(index)) return;
      setCurrent(index);
      changeRef.current?.(index);
    });

    return () => {
      flipRef.current = null;
      try {
        book.destroy();
      } catch {
        // destroy() throws if the mount was already torn down
      }
      queueMicrotask(() => roots.forEach((root) => root.unmount()));
      host.replaceChildren();
    };
    // Rebuilding the book is the only safe way to react to content changes,
    // since StPageFlip takes ownership of the page DOM after loadFromHTML.
  }, [album, leaves]);

  const goNext = useCallback(() => {
    const book = flipRef.current;
    if (!book) return;
    const last = book.getPageCount() - 1;
    if (book.getCurrentPageIndex() >= last) {
      if (loop) book.turnToPage(0);
      return;
    }
    book.flipNext();
  }, [loop]);

  const goPrev = useCallback(() => {
    flipRef.current?.flipPrev();
  }, []);

  useAutoplay({
    enabled: autoplay,
    speed: autoplaySpeed,
    paused: interacted,
    onTick: goNext,
  });

  const swipe = useSwipe(goNext, goPrev);

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    // In RTL the left arrow advances, mirroring the physical turn direction.
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      goNext();
    } else if (event.key === "ArrowRight") {
      event.preventDefault();
      goPrev();
    }
  };

  return (
    <div
      className="ae-flip"
      tabIndex={0}
      role="group"
      aria-label={album.title}
      onKeyDown={handleKeyDown}
    >
      <div className="ae-flip__stage" {...swipe}>
        <div ref={hostRef} className="ae-flip__book" />
        <button
          type="button"
          className="ae-flip__zone ae-flip__zone--next"
          onClick={goNext}
          aria-label="הדף הבא"
        />
        <button
          type="button"
          className="ae-flip__zone ae-flip__zone--prev"
          onClick={goPrev}
          aria-label="הדף הקודם"
        />
      </div>

      {showControls ? (
        <div className="ae-flip__controls">
          <button type="button" className="ae-btn" onClick={goPrev}>
            הקודם
          </button>
          <span className="ae-flip__counter">
            {Math.min(current + 1, total)} / {total}
          </span>
          <button type="button" className="ae-btn" onClick={goNext}>
            הבא
          </button>
          {autoplay ? (
            <button
              type="button"
              className="ae-btn ae-btn--ghost"
              onClick={() => setInteracted((paused) => !paused)}
            >
              {interacted ? "המשך הצגה" : "השהה הצגה"}
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

/**
 * Swipe-to-turn for touch, which the library would normally provide.
 *
 * Its own pointer handling is off because the book is mirrored, so the gesture
 * is measured here instead — in viewport coordinates, which the mirror does not
 * touch. A finger moving rightwards advances: the reader is dragging the
 * left-hand leaf across the spine, the same page the "next" tap zone covers.
 *
 * Mouse drags are ignored. Selecting a line of a greeting would otherwise turn
 * the page out from under the selection.
 */
function useSwipe(onNext: () => void, onPrev: () => void) {
  const from = useRef<{ x: number; y: number; id: number } | null>(null);
  const turned = useRef(false);

  return {
    onPointerDown(event: React.PointerEvent) {
      turned.current = false;
      from.current =
        event.pointerType === "mouse" || !event.isPrimary
          ? null
          : { x: event.clientX, y: event.clientY, id: event.pointerId };
    },
    onPointerUp(event: React.PointerEvent) {
      const start = from.current;
      from.current = null;
      if (!start || start.id !== event.pointerId) return;

      const dx = event.clientX - start.x;
      // A gesture that travelled further down than across was a scroll that
      // happened to drift, not a turn.
      if (Math.abs(dx) < SWIPE_THRESHOLD) return;
      if (Math.abs(dx) <= Math.abs(event.clientY - start.y)) return;

      turned.current = true;
      if (dx > 0) onNext();
      else onPrev();
    },
    onPointerCancel() {
      from.current = null;
    },
    // A swipe ending over a tap zone still emits a click, which would turn a
    // second page. Caught on the way down, before the zone sees it.
    onClickCapture(event: React.MouseEvent) {
      if (!turned.current) return;
      turned.current = false;
      event.stopPropagation();
      event.preventDefault();
    },
  };
}

function renderLeaf(album: LayoutViewProps["album"], slide: AlbumSlide) {
  if (slide.kind === "page") {
    return <GreetingPage album={album} page={slide.page} part={slide.part} />;
  }
  if (slide.kind === "blank") {
    return <BlankPage album={album} />;
  }
  return (
    <CoverWrapper
      album={album}
      face={slide.kind === "front-cover" ? "front" : "back"}
    />
  );
}

/** Covers are rigid boards; everything inside the book is a soft sheet. */
function coverDensity(slide: AlbumSlide): "hard" | "soft" {
  return slide.kind === "front-cover" || slide.kind === "back-cover"
    ? "hard"
    : "soft";
}
